<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_once __DIR__.'/read-model.php';require_once __DIR__.'/vehicle-store.php';require_once __DIR__.'/taxonomy-store.php';
try{kalite_filo_admin_start_session();kalite_filo_admin_require_authentication();if(($_SERVER['REQUEST_METHOD']??'')==='GET')kalite_filo_admin_json(['groups'=>kalite_filo_admin_taxonomy()]);kalite_filo_admin_require_method('POST');kalite_filo_admin_require_same_origin();kalite_filo_admin_require_csrf();$body=kalite_filo_admin_read_json();$operation=(string)($body['operation']??'');$field=(string)($body['field']??'');$value=trim((string)($body['value']??''));$next=trim((string)($body['nextValue']??''));if(!in_array($field,KALITE_FILO_TAXONOMY_FIELDS,true)||$value===''||mb_strlen($value)>100)throw new InvalidArgumentException('validation_failed');$groups=kalite_filo_admin_taxonomy();$entry=null;foreach($groups[$field] as $item)if($item['value']===$value)$entry=$item;$custom=kalite_filo_admin_custom_taxonomy();$custom[$field]??=[];if($operation==='create'){if($entry!==null)throw new InvalidArgumentException('duplicate');$custom[$field][]=$value;}elseif($operation==='update'){if(!is_array($entry)||!$entry['custom']||$entry['usageCount']>0||$next===''||mb_strlen($next)>100)throw new InvalidArgumentException('tag_in_use');$custom[$field]=array_values(array_map(fn($v)=>$v===$value?$next:$v,$custom[$field]));}elseif($operation==='delete'){if(!is_array($entry)||!$entry['custom']||$entry['usageCount']>0)throw new InvalidArgumentException('tag_in_use');$custom[$field]=array_values(array_filter($custom[$field],fn($v)=>$v!==$value));}else throw new InvalidArgumentException('validation_failed');kalite_filo_admin_write_taxonomy($custom);kalite_filo_admin_audit('vehicle_tag_'.$operation,'success',['field'=>$field,'value'=>$value]);kalite_filo_admin_json(['groups'=>kalite_filo_admin_taxonomy()]);}catch(InvalidArgumentException $e){kalite_filo_admin_json(['error'=>$e->getMessage()],422);}catch(Throwable $e){error_log('Tags failed: '.$e->getMessage());kalite_filo_admin_json(['error'=>'service_unavailable'],503);}
